from __future__ import annotations

import fnmatch
import re

from .models import PackageChange

# Match a requirement line: an optional extras group, a version operator and
# the pinned version. Environment markers, hashes and inline comments are
# excluded from the captured version token.
_REQUIREMENT_RE = re.compile(
    r"^\s*"
    r"(?P<name>[A-Za-z0-9][A-Za-z0-9._-]*)"
    r"\s*(?:\[[^\]]*\])?\s*"
    r"(?:==|===|~=|!=|>=|<=|>|<)\s*"
    r"(?P<version>[^\s;#]+)"
)

_TRACKED_FILE_PATTERN = "requirements*.txt"


def _normalize_name(name: str) -> str:
    """Normalize a package name per PEP 503."""
    return re.sub(r"[-_.]+", "-", name).lower()


def _is_tracked_file(path: str) -> bool:
    """Return True if the diff file path is a tracked requirements file."""
    basename = path.rsplit("/", 1)[-1]
    return fnmatch.fnmatch(basename, _TRACKED_FILE_PATTERN)


def _strip_file_prefix(path: str) -> str:
    """Strip the diff a/ or b/ prefix and any trailing metadata from a path."""
    # Diff headers may include a trailing tab and timestamp.
    path = path.split("\t", 1)[0].strip()
    if path.startswith(("a/", "b/")):
        path = path[2:]
    return path


def _parse_requirement(content: str) -> tuple[str, str] | None:
    """Parse a requirement line into a (normalized name, version) tuple."""
    # Ignore comment lines and strip inline comments before parsing.
    if content.lstrip().startswith("#"):
        return None
    content = content.split("#", 1)[0].strip()
    if not content:
        return None
    match = _REQUIREMENT_RE.match(content)
    if match is None:
        return None
    return _normalize_name(match.group("name")), match.group("version")


def parse_diff(diff_text: str) -> list[PackageChange]:
    """Parse a unified diff into a list of package changes.

    Only files matching ``requirements*.txt`` are considered. Package names are
    normalized per PEP 503, inline comments are stripped, comment lines are
    ignored and lines with no version change are skipped.
    """
    # Per file: map of normalized name -> version for removed / added lines.
    removed: dict[str, str] = {}
    added: dict[str, str] = {}
    tracked = False

    changes: list[PackageChange] = []
    seen: set[str] = set()

    def flush() -> None:
        """Emit package changes for the current file's collected lines."""
        for name, new_version in added.items():
            old_version = removed.get(name)
            if old_version == new_version:
                # Version did not change; ignore.
                continue
            if name in seen:
                continue
            seen.add(name)
            changes.append(PackageChange(name, old_version, new_version))

    for line in diff_text.splitlines():
        if line.startswith("+++ "):
            # Header for the new file: flush the previous file and switch.
            flush()
            removed = {}
            added = {}
            path = _strip_file_prefix(line[4:])
            tracked = path != "/dev/null" and _is_tracked_file(path)
            continue
        if line.startswith("--- "):
            # Old-file header; carries no content we track.
            continue
        if line.startswith(("diff ", "index ", "@@", "new file", "deleted file")):
            continue
        if not tracked:
            continue
        if line.startswith("+"):
            parsed = _parse_requirement(line[1:])
            if parsed is not None:
                added[parsed[0]] = parsed[1]
        elif line.startswith("-"):
            parsed = _parse_requirement(line[1:])
            if parsed is not None:
                removed[parsed[0]] = parsed[1]

    flush()
    return changes
