from __future__ import annotations

from urllib.parse import urlparse

import requests

_TIMEOUT = 30

# Hostnames that are accepted as known code hosts. The match must be exact to
# reject domain-suffix lookalikes such as ``github.com.evil.com``.
_KNOWN_CODE_HOSTS = frozenset(
    {"github.com", "gitlab.com", "www.github.com", "www.gitlab.com"}
)

_RECOGNIZED_PUBLISHER = "GitHub"


class PypiPackageInfo:
    """Information fetched from PyPI for a specific package version."""

    def __init__(
        self,
        project_urls: dict,
        repo_url: str | None,
        file_provenance_urls: list[str],
        found: bool,
    ) -> None:
        """Initialize package info."""
        self.project_urls = project_urls
        self.repo_url = repo_url
        self.file_provenance_urls = file_provenance_urls
        self.found = found


class ProvenanceResult:
    """The result of a provenance/attestation check."""

    def __init__(
        self,
        has_attestation: bool,
        publisher_kind: str | None,
        recognized_publisher: bool,
        detail: str,
    ) -> None:
        """Initialize a provenance result."""
        self.has_attestation = has_attestation
        self.publisher_kind = publisher_kind
        self.recognized_publisher = recognized_publisher
        self.detail = detail


def _clean(value: str) -> str:
    """Strip backtick and newline characters from a string."""
    return value.replace("`", "").replace("\r", "").replace("\n", "").strip()


def _get_json(url: str) -> tuple[int | None, object]:
    """Fetch a URL and parse the JSON body.

    Returns a tuple of (status_code, parsed_json). ``status_code`` is ``None``
    on a network error and ``parsed_json`` is ``None`` on invalid JSON.
    """
    try:
        response = requests.get(url, timeout=_TIMEOUT)
    except requests.RequestException:
        return None, None
    try:
        data = response.json()
    except ValueError:
        data = None
    return response.status_code, data


def _extract_project_urls(data: dict) -> dict:
    """Extract the project_urls mapping from a PyPI JSON response."""
    info = data.get("info") or {}
    project_urls = info.get("project_urls")
    return project_urls if isinstance(project_urls, dict) else {}


def _is_known_code_host(url: str) -> bool:
    """Return True if the URL's hostname is exactly a known code host."""
    try:
        hostname = urlparse(url).hostname
    except ValueError:
        return False
    return hostname is not None and hostname.lower() in _KNOWN_CODE_HOSTS


def _select_repo_url(project_urls: dict) -> str | None:
    """Select a source repository URL from the project URLs."""
    # Prefer the Source / Repository keys when they point to a known host.
    for key in ("Source", "Repository"):
        value = project_urls.get(key)
        if isinstance(value, str):
            cleaned = _clean(value)
            if _is_known_code_host(cleaned):
                return cleaned
    # Otherwise scan all values for a URL on a known code host.
    for value in project_urls.values():
        if isinstance(value, str):
            cleaned = _clean(value)
            if _is_known_code_host(cleaned):
                return cleaned
    return None


def _build_provenance_urls(name: str, version: str, data: dict) -> list[str]:
    """Build the integrity provenance URL for the first listed file."""
    urls = data.get("urls")
    if not isinstance(urls, list) or not urls:
        return []
    first = urls[0]
    if not isinstance(first, dict):
        return []
    filename = first.get("filename")
    if not filename:
        return []
    return [
        f"https://pypi.org/integrity/{name}/{version}/{filename}/provenance",
    ]


def fetch_package_info(name: str, version: str) -> PypiPackageInfo:
    """Fetch package metadata from PyPI for a specific version."""
    versioned_url = f"https://pypi.org/pypi/{name}/{version}/json"
    latest_url = f"https://pypi.org/pypi/{name}/json"

    status, data = _get_json(versioned_url)
    if status == 200 and isinstance(data, dict):
        project_urls = _extract_project_urls(data)
        return PypiPackageInfo(
            project_urls=project_urls,
            repo_url=_select_repo_url(project_urls),
            file_provenance_urls=_build_provenance_urls(name, version, data),
            found=True,
        )

    if status == 404:
        # Fall back to the latest endpoint to surface metadata, but the exact
        # version is not on PyPI.
        latest_status, latest_data = _get_json(latest_url)
        if latest_status == 200 and isinstance(latest_data, dict):
            project_urls = _extract_project_urls(latest_data)
            return PypiPackageInfo(
                project_urls=project_urls,
                repo_url=_select_repo_url(project_urls),
                file_provenance_urls=[],
                found=False,
            )
        return PypiPackageInfo(
            project_urls={}, repo_url=None, file_provenance_urls=[], found=False
        )

    # Network error, 5xx or invalid JSON on the versioned endpoint.
    return PypiPackageInfo(
        project_urls={}, repo_url=None, file_provenance_urls=[], found=False
    )


