from __future__ import annotations

from .diff import parse_diff
from .models import (
    CheckKind,
    CheckResult,
    CheckRunResult,
    CheckStatus,
    PackageChange,
)
from .pypi import ProvenanceResult, PypiPackageInfo, check_provenance, fetch_package_info


def _build_checks(
    info: PypiPackageInfo, provenance: ProvenanceResult
) -> dict[CheckKind, CheckResult]:
    """Build the check results for a single package."""
    if not info.found:
        message = "Package version not found on PyPI; supply-chain checks cannot run."
        return {kind: CheckResult(CheckStatus.FAIL, message) for kind in CheckKind}

    checks: dict[CheckKind, CheckResult] = {}

    # Checks derived from the provenance attestation.
    if provenance.has_attestation and provenance.recognized_publisher:
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.PASS,
            f"Uploaded with a recognised trusted publisher ({provenance.publisher_kind}).",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.PASS,
            f"Release attested by recognised publisher ({provenance.publisher_kind}).",
        )
    elif provenance.has_attestation:
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.WARN,
            f"Attestation present but publisher unrecognised ({provenance.publisher_kind}).",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            "Release attestation present but publisher unrecognised "
            f"({provenance.publisher_kind}); manual review required.",
        )
    else:
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.WARN,
            f"No provenance attestation present. {provenance.detail}".strip(),
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            "No provenance attestation; verify the release pipeline manually.",
        )

    # Checks derived from the advertised source repository.
    if info.repo_url:
        checks[CheckKind.REPO_PUBLIC] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            f"Verify the source repository is public: {info.repo_url}",
        )
        checks[CheckKind.PR_LINK] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            "Verify the change links to a corresponding upstream PR or release.",
        )
    else:
        checks[CheckKind.REPO_PUBLIC] = CheckResult(
            CheckStatus.FAIL,
            "Package does not advertise a source repository URL.",
        )
        checks[CheckKind.PR_LINK] = CheckResult(
            CheckStatus.FAIL,
            "No source repository advertised; cannot locate an upstream PR.",
        )

    return checks


def run_checks(pr_number: int, diff_text: str) -> CheckRunResult:
    """Parse a diff, fetch PyPI info and run all checks for each package."""
    packages: list[PackageChange] = []
    for change in parse_diff(diff_text):
        info = fetch_package_info(change.name, change.new_version)
        provenance = check_provenance(info)
        packages.append(
            PackageChange(
                name=change.name,
                old_version=change.old_version,
                new_version=change.new_version,
                checks=_build_checks(info, provenance),
                repo_url=info.repo_url,
            )
        )
    return CheckRunResult(pr_number, packages)
